// ATENCAO: o formulario nao pergunta o empreendimento. Enquanto nao existir
// essa pergunta, defina aqui qual empreendimento recebe as respostas.
const EMPREENDIMENTO_PADRAO = 'high-tower';

const d = $input.item.json;

// Lookup tolerante: ignora espaços/maiúsculas e tenta sufixos _1/_2
// (n8n sufixa headers duplicados em algumas versões)
const v = (field) => {
  const alvo = field.trim().toLowerCase();
  const candidatos = [];
  for (const key of Object.keys(d)) {
    const k = key.trim().toLowerCase();
    if (k === alvo || k === `${alvo}_1` || k === `${alvo}_2`) {
      candidatos.push(String(d[key] ?? '').trim());
    }
  }
  return candidatos.find(c => c !== '') ?? '';
};

// A lista suspensa do formulario devolve "1. Contrato de...". O prefixo
// numerico precisa sair, senao o mapa blocosPorTipo nunca casa.
const tipo = v('Qual documento você deseja gerar?')
  .replace(/^\s*\d+\s*[.)-]\s*/, '')
  .trim();

// ---------- Blocos comuns ----------
const dadosGerais = {
  dataHora: v('Carimbo de data/hora'),
  dataDocumento: v('Data do documento'),
  cidadeUf: v('Cidade/UF da assinatura - ex:(Aracruz/ES)'),
  responsavel: v('Responsável interno pelo preenchimento'),
};

const comprador = {
  nome: v('Nome completo do comprador'),
  cpf: v('CPF do comprador'),
  nacionalidade: v('Nacionalidade do comprador'),
  estadoCivil: v('Estado civil do comprador'),
  profissao: v('Profissão do comprador'),
  rg: v('RG do comprador'),
  orgaoEmissorRg: v('Órgão emissor do RG do comprador'),
  endereco: v('Endereço completo do comprador'),
  cep: v('CEP do comprador'),
  telefone: v('Telefone com DDD do comprador'),
  email: v('E-mail do comprador'),
};

const temConjuge = v('O comprador possui cônjuge que deve constar no documento?').toLowerCase().startsWith('s');
const conjuge = temConjuge ? {
  nome: v('Nome completo do cônjuge'),
  cpf: v('CPF do cônjuge'),
  nacionalidade: v('Nacionalidade do cônjuge'),
  profissao: v('Profissão do cônjuge'),
  rg: v('RG do cônjuge'),
  orgaoEmissorRg: v('Órgão emissor do RG do cônjuge'),
} : null;

const testemunhas = [1, 2]
  .map(n => ({ nome: v(`Nome da testemunha ${n}`), cpf: v(`CPF da testemunha ${n}`) }))
  .filter(t => t.nome || t.cpf);

// ---------- Compra e Venda ----------
const parcelas = [];
for (let n = 1; n <= 5; n++) {
  const tipoParcela = v(`Tipo da parcela ${n}`);
  if (!tipoParcela) continue;
  parcelas.push({
    numero: n,
    tipo: tipoParcela,
    vencimentoInicial: v(`Data inicial de vencimento da parcela ${n}`),
    valorUnitario: v(`Valor unitário da parcela ${n}`),
    quantidade: v(`Quantidade da parcela ${n}`),
    percentual: v(`Percentual da parcela ${n}`),
    reajustavel: v(`A parcela ${n} é reajustável?`),
    indice: v(`Índice da parcela ${n}`),
    formaPagamento: v(`Forma de pagamento da parcela ${n}`),
  });
}

const compraVenda = {
  unidade: {
    tipo: v('Tipo da unidade - ex:(apartamento)'),
    numero: v('Número da unidade'),
    numeroExtenso: v('Número da unidade por extenso'),
    vagasGaragem: v('Quantidade de vagas de garagem'),
    numerosVagas: v('Números das vagas'),
    areaPrivativa: v('Área privativa (m²)'),
    areaConstrucao: v('Área de construção (m²)'),
    fracaoIdeal: v('Fração ideal'),
    descricaoPlanta: v('Descrição da planta - ex:( 3 quartos, 1 suíte, varanda gourmet...)'),
  },
  precoTotal: v('Preço total do imóvel (R$)'),
  precoExtenso: v('Preço total por extenso'),
  qtdTiposParcelas: v('Quantos tipos de parcelas existem nesta negociação?'),
  parcelas,
  observacaoEspecial: v('Existe alguma observação especial na negociação?'),
  temPersonalizacao: v('Existe personalização de unidade / ajuste comercial que precisa constar?'),
  descricaoPersonalizacao: v('Descreva a personalização / ajuste'),
};

// ---------- Anexo (usa Tipo/Número da unidade sem o "ex:") ----------
const anexo = {
  tipoUnidade: v('Tipo da unidade'),
  numeroUnidade: v('Número da unidade'),
  numeroUnidadeExtenso: v('Número da unidade por extenso'),
};

// ---------- SCP ----------
const scp = {
  razaoSocial: v('Razão social do empreendimento'),
  cnpj: v('CNPJ'),
  enderecoEmpresa: v('Endereço completo da empresa'),
  cepEmpresa: v('CEP da empresa'),
  valorEntrada: v('Valor da Entrada'),
  numeroUnidades: v('Número de Unidades'),
  entrada: v('Entrada'),
  parcelaMensal: v('Parcela Mensal'),
  parcelaIntermediaria: v('Parcela Intermediaria'),
  parcelaAnual: v('Parcela Anual'),
  parcelaChave: v('Parcela Chave'),
  quantidade: v('Quantidade'),
  quantidadeMensal: v('Quantidade Mensal'),
  quantidadeIntermediaria: v('Quantidade Intermediaria'),
  quantidadeAnual: v('Quantidade Anual'),
  quantidadeChave: v('Quantidade Chave'),
  valor: v('Valor'),
  valorMensal: v('Valor Mensal'),
  valorIntermediario: v('Valor Intermediario'),
  valorAnual: v('Valor Anual'),
  valorChave: v('Valor Chave'),
  valorTotal: v('Valor Total'),
  valorTotalMensal: v('Valor Total Mensal'),
  valorTotalIntermediario: v('Valor Total Intermediario'),
  valorTotalAnual: v('Valor Total Anual'),
  valorTotalChave: v('Valor Total Chave'),
};

// ---------- Empréstimo ----------
const emprestimo = {
  nomePj: v('Nome da Pessoa Jurídica'),
  cnpj: v('CNPJ'),
  endereco: v('Endereço completo'),
  cep: v('CEP'),
  residencia: v('Residência?'),
  enderecoImovel: v('Endereço do imóvel'),
};

// ---------- Permuta ----------
const areasPermuta = [];
for (let n = 1; n <= 7; n++) {
  const end = v(`Endereço Área ${n}`);
  if (!end) continue;
  areasPermuta.push({
    numero: n,
    endereco: end,
    inscricao: v(`Inscrição Área ${n}`),
    areaTerreno: v(`Área do Terreno Área ${n}`),
    areaConstruida: v(`Área Construída Área ${n}`),
    matriculaRgi: v(`Matrícula (RGI) Área ${n}`),
  });
}

const permuta = {
  areas: areasPermuta,
  pctVgvUnidades: v('Porcentagem referente ao Valor Geral de Venda das Unidades'),
  pctVgvPosViabilidade: v('Nova porcentagem correspondente do VGV, após realização dos estudos de viabilidade'),
  alteracaoPctVgv: v('Alteração da porcentagem do VGV por razões técnicas e/ou mercadológicas'),
  pctVgvEntrega: v('Porcentagem apurada do VGV das Unidades mediante a entrega'),
  pctValorGlobalPermuta: v('Porcentagem do valor global atribuído à permuta correspondente ao VGV'),
  pctValorPresentePermutaFisica: v('Porcentagem do valor presente da permuta física correspondente ao VGV'),
  pctPermutaFisica: v('Porcentagem da permuta física correspondente ao VGV'),
  descricaoAreas: v('Descrição das áreas do imóvel'),
  pctVgvQuitacaoUnidades: v('Porcentagem do VGV para quitação via entrega de unidades autônomas'),
  pctVgvPosProjetoArquitetonico: v('Porcentagem do VGV após estudos de viabilidade e aprovação do projeto arquitetônico'),
  data: v('Data'),
  nomeEmpreendimento: v('Nome do Empreendimento'),
  primeiroPermutante: v('Dados Primeiro Permutante'),
  segundoPermutante: v('Dados Segundo Permutante'),
  intermediadora: v('Intermediadora (caso tenha)'),
  precoSegundaPermutante: v('Preço Segunda Permutante'),
  banco: v('Banco do Pagamento'),
  agencia: v('AG'),
  contaCorrente: v('Conta Corrente'),
  op: v('OP'),
  titularidade: v('Titularidade'),
  valorMensalMateriais: v('Valor Mensal Fornecimento de Materiais'),
};

// ---------- Monta payload por tipo ----------
const blocosPorTipo = {
  'Contrato de Promessa de Compra e Venda': { compraVenda },
  'Anexo ao Contrato de Promessa de Compra e Venda': { anexo },
  'Termo de Anuência com Outorga de Poderes': {},
  'Termo de Ciência e Anuência para Empréstimo': { emprestimo },
  'Termo de Adesão Preliminar SCP': { scp },
  'Contrato de Permuta': { permuta },
};

return [{
  json: {
    // Flat: compatibilidade com Criar Cliente / Criar Contrato
    tipoDocumento: tipo,
    nome: comprador.nome || permuta.primeiroPermutante,
    cpfCnpj: comprador.cpf || scp.cnpj,
    telefone: comprador.telefone,
    email: comprador.email,
    responsavel: dadosGerais.responsavel,

    // A aplicacao resolve o id da unidade a partir do numero + empreendimento.
    empreendimentoId: EMPREENDIMENTO_PADRAO,
    unidadeNumero: v('Número da unidade'),
    dataHora: dadosGerais.dataHora,

    // Estruturado: tudo que o gerador de documento precisa
    documento: {
      tipo,
      dadosGerais,
      comprador,
      conjuge,
      testemunhas,
      ...(blocosPorTipo[tipo] ?? { compraVenda, anexo, emprestimo, scp, permuta }),
    },
  },
}];

